python3 -c "
import numpy as np
lines=open('start.xyz').read().splitlines()[2:]
els=[]; coords=[]
for l in lines:
    s=l.split(); els.append(s[0]); coords.append([float(x) for x in s[1:4]])
c=np.array(coords)
n=len(els)
mind=99; pair=None
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(c[i]-c[j])
        if d<mind: mind=d; pair=(i,j)
print('min distance', mind, pair, els[pair[0]], els[pair[1]])
# count distances < 1.0
cnt=0
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(c[i]-c[j])
        if d<1.0: cnt+=1; print('close:', i, els[i], j, els[j], round(d,3))
print('num close pairs', cnt)
"
